<script setup>
import StarterKit from '@tiptap/starter-kit'
import Document from '@tiptap/extension-document'
import Mention from '@tiptap/extension-mention'
import Paragraph from '@tiptap/extension-paragraph'
import Text from '@tiptap/extension-text'
import { Editor, EditorContent } from '@tiptap/vue-3'
import suggestion from './suggestion.js'
</script>

<template>
  <div v-if="editor">
    <editor-content :editor="editor" />
  </div>
</template>

<script>
export default {
  props: ['project', 'modelValue'],
  emits: ['update:modelValue'],
  data() {
    return {
      editor: null,
    }
  },

  watch: {
    modelValue(value) {
      const isSame = this.editor.getHTML() === value

      if (isSame) {
        return
      }

      this.editor.commands.setContent(value)
    },
  },

  async mounted() {
    const search = await this.onSearch.bind(this)
    const onSelect = this.onSelect.bind(this)
    this.editor = new Editor({
      extensions: [
        StarterKit,
        Document,
        Paragraph,
        Text,
        Mention.configure({
          HTMLAttributes: {
            class: 'mention',
          },
          suggestion: suggestion({ search }),
        }),
      ],
      content: this.modelValue,
      onUpdate: () => {
        this.$emit('update:modelValue', this.editor.getHTML())
      },
    })
  },
  methods: {
    onSearch(query) {
      return Promise.resolve(query.length > 2 ? this.project?.$state.searchMentions(query, 6) : [])
    },
    onSelect(item) {
      console.log("Suggestion selected", item)
    }
  },
  beforeUnmount() {
    this.editor.destroy()
  },
}
</script>

